{"command": "python3 -c "
# Check: can a 4-sorter with 5 comparators be done in 5 layers (one per layer)?
def apply_comp(vals, i, j):
    # ascending: smaller on left
    if vals[i] - vals[j] > 0:
        vals[i], vals[j] = vals[j], vals[i]
    return vals

# Test all 4! = 24 permutations
import itertools
comps = [(0,1), (1,2), (2,3), (0,1), (1,2)]

def test_sort(comps):
    for perm in itertools.permutations(range(4)):
        vals = list(perm)
        for i, j in comps:
            apply_comp(vals, i, j)
        for k in range(3):
            if vals[k] - vals[k+1] > 0:
                return False, perm
    return True, None

ok, fail = test_sort(comps)
print(f'5 sequential adjacent comps sort 4 inputs: {ok}')
if not ok:
    print(f'  failed on: {fail}')

# Odd-even transposition (5 comps)
comps2 = [(0,1), (2,3), (1,2), (0,1), (2,3)]
ok2, fail2 = test_sort(comps2)
print(f'odd-even 5 comps sort 4 inputs: {ok2}')
" 2>&1
